//! LAB-6's types, and the text forms `statespace check` reads and writes. Course-supplied: reference
//! module, earns nothing. You do not edit this file; your work is in the files marked as yours.
//!
//! A command is a `Transfer`. Your compiler turns it into a `Plan`: a list of SQL statements, each with
//! the number of rows it must touch and the outcome to return when it does not. `statespace check` runs
//! the plan on PostgreSQL: BEGIN (or your runtime's statements), every step in order, then COMMIT. When a
//! step touches a number of rows its `expect` does not allow, the transaction is rolled back and the
//! command's outcome is that step's `on_mismatch`. When the server raises an error, the transaction is
//! rolled back and the outcome is `Sqlstate(<code>)`. A plan may decide its outcome before any SQL runs
//! (`decided`): nothing is sent and the database is unchanged.
//!
//! The reference interpreter that grades you decides a transfer in this order: a self-transfer (your
//! LAB-3.7 decision, in decision.rs), then `NoSuchAccount(From)`, then `NoSuchAccount(To)`, then
//! `Insufficient` (the balance is below the amount), else it commits.

use std::collections::BTreeMap;
use std::fmt;

pub type Id = i64;

/// The accounts every LAB-6 check opens before it runs your plans (id, balance).
pub const ACCOUNTS: [(Id, i64); 5] = [(1, 100), (2, 50), (3, 0), (4, 250), (5, 1000)];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Transfer {
    pub from: Id,
    pub to: Id,
    pub amount: i64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    From,
    To,
}

/// What a command returned: its outcome class.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Outcome {
    Committed,
    Insufficient,
    NoSuchAccount(Side),
    SelfTransfer,
    /// The server refused with this SQLSTATE, such as 23514 (a CHECK) or 22003 (out of range).
    Sqlstate(String),
}

/// What a step is for. The course's mutation operators (LAB-6.3, LAB-6.4) find your debit and your
/// credit by their role, so give each step its true one.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Role {
    Check,
    Debit,
    Credit,
    Other,
}

/// How many rows a step must touch: a SELECT's rows, or an UPDATE's or INSERT's affected rows.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Expect {
    Exactly(u64),
    AtMost(u64),
    Any,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Step {
    pub role: Role,
    /// One SQL statement, with $1, $2, ... for its parameters.
    pub sql: String,
    pub params: Vec<i64>,
    pub expect: Expect,
    pub on_mismatch: Outcome,
}

#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Plan {
    pub decided: Option<Outcome>,
    pub steps: Vec<Step>,
}

/// What a check saw after one command: its outcome and alpha of the database afterwards.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Observation {
    pub outcome: Outcome,
    pub balances: BTreeMap<Id, i64>,
}

/// One attempt of a command, as the retry loop sees it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Attempt {
    Committed,
    Refused(Outcome),
    Sqlstate(String),
}

/// The database as rows (D): `acct(id, bal)` and `holds(acct, amt)`. A NULL is `None`.
#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Db {
    pub acct: Vec<(Option<Id>, Option<i64>)>,
    pub holds: Vec<(Option<Id>, Option<i64>)>,
}

/// The abstract state (S): each account's balance, and the amount held against it.
#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct State {
    pub bal: BTreeMap<Id, i64>,
    pub held: BTreeMap<Id, i64>,
}

/// A small seeded generator (splitmix64), so your generator needs no crate.
#[derive(Clone, Debug)]
pub struct Rng(u64);

impl Rng {
    pub fn new(seed: u64) -> Rng {
        Rng(seed)
    }
    pub fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
    /// A number in lo..=hi.
    pub fn range(&mut self, lo: i64, hi: i64) -> i64 {
        lo + (self.next_u64() % ((hi - lo + 1) as u64)) as i64
    }
    /// True with probability `percent` in 100.
    pub fn chance(&mut self, percent: u64) -> bool {
        self.next_u64() % 100 < percent
    }
}

// ------------------------------------------------------------------------------------------ text forms

impl fmt::Display for Outcome {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Outcome::Committed => write!(f, "Committed"),
            Outcome::Insufficient => write!(f, "Insufficient"),
            Outcome::NoSuchAccount(Side::From) => write!(f, "NoSuchAccount(from)"),
            Outcome::NoSuchAccount(Side::To) => write!(f, "NoSuchAccount(to)"),
            Outcome::SelfTransfer => write!(f, "SelfTransfer"),
            Outcome::Sqlstate(code) => write!(f, "sqlstate:{}", code),
        }
    }
}

impl Outcome {
    pub fn parse(token: &str) -> Option<Outcome> {
        Some(match token {
            "Committed" => Outcome::Committed,
            "Insufficient" => Outcome::Insufficient,
            "NoSuchAccount(from)" => Outcome::NoSuchAccount(Side::From),
            "NoSuchAccount(to)" => Outcome::NoSuchAccount(Side::To),
            "SelfTransfer" => Outcome::SelfTransfer,
            other => Outcome::Sqlstate(other.strip_prefix("sqlstate:")?.to_string()),
        })
    }
}

impl fmt::Display for Expect {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Expect::Exactly(n) => write!(f, "exactly:{}", n),
            Expect::AtMost(n) => write!(f, "atmost:{}", n),
            Expect::Any => write!(f, "any"),
        }
    }
}

impl fmt::Display for Role {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let word = match self {
            Role::Check => "check",
            Role::Debit => "debit",
            Role::Credit => "credit",
            Role::Other => "other",
        };
        write!(f, "{}", word)
    }
}

/// The plan as `statespace check` reads it.
pub fn write_plan(t: &Transfer, plan: &Plan) -> String {
    let mut out = format!("plan {} {} {}\n", t.from, t.to, t.amount);
    if let Some(outcome) = &plan.decided {
        out.push_str(&format!("decided {}\n", outcome));
    }
    for step in &plan.steps {
        let params: Vec<String> = step.params.iter().map(|p| p.to_string()).collect();
        let params = if params.is_empty() { "-".to_string() } else { params.join(",") };
        let sql = step.sql.replace('\n', " ");
        out.push_str(&format!("step {} {} {} {} {}\n", step.role, step.expect, step.on_mismatch, params, sql.trim()));
    }
    out.push_str("end\n");
    out
}

pub fn parse_transfer(line: &str) -> Option<Transfer> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    if parts.len() != 4 || parts[0] != "transfer" {
        return None;
    }
    Some(Transfer { from: parts[1].parse().ok()?, to: parts[2].parse().ok()?, amount: parts[3].parse().ok()? })
}

pub fn write_transfer(t: &Transfer) -> String {
    format!("transfer {} {} {}", t.from, t.to, t.amount)
}

/// `1=100,2=50` (or `-` for no account).
pub fn parse_balances(token: &str) -> Option<BTreeMap<Id, i64>> {
    let mut out = BTreeMap::new();
    if token == "-" {
        return Some(out);
    }
    for pair in token.split(',') {
        let (k, v) = pair.split_once('=')?;
        out.insert(k.parse().ok()?, v.parse().ok()?);
    }
    Some(out)
}

pub fn parse_observation(outcome: &str, balances: &str) -> Option<Observation> {
    Some(Observation { outcome: Outcome::parse(outcome)?, balances: parse_balances(balances)? })
}

pub fn parse_attempt(token: &str) -> Option<Attempt> {
    if token == "Committed" {
        return Some(Attempt::Committed);
    }
    if let Some(code) = token.strip_prefix("sqlstate:") {
        return Some(Attempt::Sqlstate(code.to_string()));
    }
    Some(Attempt::Refused(Outcome::parse(token)?))
}

fn opt(token: &str) -> Option<Option<i64>> {
    if token == "null" {
        Some(None)
    } else {
        token.parse().ok().map(Some)
    }
}

/// Reads `acct <id> <bal>` and `hold <acct> <amt>` lines into D, and `bal <id> <n>` and `held <id> <n>`
/// lines into S.
pub fn parse_db_and_state(lines: &[&str]) -> Option<(Db, State)> {
    let mut d = Db::default();
    let mut s = State::default();
    for line in lines {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() != 3 {
            return None;
        }
        match parts[0] {
            "acct" => d.acct.push((opt(parts[1])?, opt(parts[2])?)),
            "hold" => d.holds.push((opt(parts[1])?, opt(parts[2])?)),
            "bal" => {
                s.bal.insert(parts[1].parse().ok()?, parts[2].parse().ok()?);
            }
            "held" => {
                s.held.insert(parts[1].parse().ok()?, parts[2].parse().ok()?);
            }
            _ => return None,
        }
    }
    Some((d, s))
}

pub fn write_state(s: &State) -> String {
    let mut out = String::new();
    for (k, v) in &s.bal {
        out.push_str(&format!("bal {} {}\n", k, v));
    }
    for (k, v) in &s.held {
        if *v != 0 {
            out.push_str(&format!("held {} {}\n", k, v));
        }
    }
    out
}
